<?php require __DIR__.'/bootstrap.php';$u=require_admin();if(isset($_GET['toggle'])){$id=(int)$_GET['toggle'];if($id!==$u['id'])$pdo->prepare("UPDATE users SET status=IF(status='active','blocked','active') WHERE id=?")->execute([$id]);header('Location: admin_users.php');exit;}$term=trim($_GET['q']??'');$q=$pdo->prepare('SELECT u.*,p.name plan FROM users u LEFT JOIN subscriptions s ON s.user_id=u.id LEFT JOIN plans p ON p.id=s.plan_id WHERE u.name LIKE ? OR u.email LIKE ? ORDER BY u.id DESC');$q->execute(['%'.$term.'%','%'.$term.'%']);$users=$q->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Assinantes — Administração</title><link rel="stylesheet" href="assets/app.css"></head><body class="adminskin"><aside class="side"><a class="side-logo">ARENA DE <b>AÇO</b><small>ADMINISTRAÇÃO</small></a><a href="admin.php">⌂ Dashboard</a><a class="active" href="admin_users.php">♟ Assinantes</a><a href="admin_plans.php">◈ Planos</a><a href="admin_catalog.php">▣ Catálogo</a><a href="video_novo.php">▻ Vídeos</a><a href="admin_tickets.php">♧ Suporte</a></aside><main class="adminmain"><header class="adminhead"><div><h1>Assinantes</h1><span>Gerencie contas, planos e acesso.</span></div></header><form class="searchbar"><input name="q" value="<?=e($term)?>" placeholder="Buscar por nome ou e-mail"><button class="redbtn">Buscar</button></form><section class="panel user-table"><div class="tr th"><span>Cliente</span><span>Plano</span><span>Perfil</span><span>Status</span><span>Ação</span></div><?php foreach($users as $x):?><div class="tr"><span><b><?=e($x['name'])?></b><small><?=e($x['email'])?></small></span><span><?=e($x['plan']??'Sem plano')?></span><span><?=e($x['role'])?></span><span><b class="status <?=e($x['status'])?>"><?=e($x['status'])?></b></span><span><?php if($x['id']!==$u['id']):?><a class="table-action" href="?toggle=<?=$x['id']?>">Alterar status</a><?php endif?></span></div><?php endforeach?></section></main></body></html>
